@push('scripts')<script>
document.querySelectorAll('[data-plan-transform]').forEach(button=>button.addEventListener('click',async()=>{const box=document.getElementById('plan-transforme');button.disabled=true;box.classList.remove('d-none');box.textContent='Transformation en cours…';try{const response=await fetch('{{ route('plans-urgence.ia.transformer',$plan) }}',{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({action:button.dataset.planTransform})});const data=await response.json();if(!response.ok)throw new Error(data.message||'La transformation est indisponible.');box.replaceChildren();box.dir=data.dir;const title=document.createElement('h2');title.textContent=data.titre;const description=document.createElement('p');description.textContent=data.description;box.append(title,description);data.etapes.forEach(step=>{const item=document.createElement('p');item.textContent=`${step.moment} — ${step.titre}: ${step.description||''}`;box.append(item);});}catch(e){box.textContent=e.message;}finally{button.disabled=false;}}));
</script>@endpush
